function duplicateIds(nodes) {
  const counts = {};
  for (const n of nodes) {
    if (!n.id) continue;
    counts[n.id] = (counts[n.id] || 0) + 1;
  }
  return Object.keys(counts).filter((id) => counts[id] > 1).sort();
}

