function tabOrder(els) {
  const positive = els.filter((e) => e.tabindex > 0).sort((a, b) => a.tabindex - b.tabindex);
  const natural = els.filter((e) => e.tabindex === 0);
  return [...positive, ...natural].map((e) => e.name);
}

