  const out = [];
  const mains = tags.filter((t) => t === "main").length;
  if (mains === 0) out.push("missing-main");
  if (mains > 1) out.push("multiple-main");
  if (!tags.includes("h1")) out.push("missing-h1");
  return out.sort();
}

