function accessibleName(el, textById) {
  if (el.ariaLabelledby) {
    const name = el.ariaLabelledby
      .split(/\s+/)
      .filter((id) => textById[id] !== undefined)
      .map((id) => textById[id])
      .join(" ")
      .trim();
    if (name) return name;
  }
  for (const v of [el.ariaLabel, el.labelText, el.title]) {
    if (v && v.trim()) return v.trim();
  }
  return "";
}

